public List<List<String>> partition(String s) {
    List<List<String>> results = new ArrayList<>();
    backtrack(s, 0, new ArrayList<>(), results);
    return results;
}

private void backtrack(String s, int start,
                       List<String> path, List<List<String>> results) {
    if (start == s.length()) {
        results.add(new ArrayList<>(path));   // whole string consumed → record a COPY
        return;
    }
    for (int end = start; end < s.length(); end++) {
        if (isPalindrome(s, start, end)) {            // prune: only cut on a palindrome
            path.add(s.substring(start, end + 1));    // choose this prefix
            backtrack(s, end + 1, path, results);     // explore the remainder
            path.remove(path.size() - 1);             // un-choose
        }
    }
}

private boolean isPalindrome(String s, int lo, int hi) {
    while (lo < hi) {
        if (s.charAt(lo++) != s.charAt(hi--)) return false;
    }
    return true;
}

