def partition(self, s: str) -> list[list[str]]:
    results: list[list[str]] = []

    def is_palindrome(lo: int, hi: int) -> bool:
        while lo < hi:
            if s[lo] != s[hi]:
                return False
            lo += 1
            hi -= 1
        return True

    def backtrack(start: int, path: list[str]) -> None:
        if start == len(s):
            results.append(path[:])              # whole string consumed → record a COPY
            return
        for end in range(start, len(s)):
            if is_palindrome(start, end):        # prune: only cut on a palindrome
                path.append(s[start:end + 1])    # choose this prefix
                backtrack(end + 1, path)         # explore the remainder
                path.pop()                       # un-choose

    backtrack(0, [])
    return results

